-- description: Add immutable evidence for progressive commercial capability rollouts
-- rollback: Disable rollout feature flags first; retain rollout records for audit, then drop these tables only after the observation window
-- minimum-app-version: 0.1.0
CREATE TABLE operations.release_rollouts(id text PRIMARY KEY,release text NOT NULL,capability text NOT NULL,phase text NOT NULL CHECK(phase IN('off','internal','canary','paid','paused')),cohort text NOT NULL,feature_flag_key text NOT NULL,gates jsonb NOT NULL,observation jsonb NOT NULL,reason text NOT NULL,actor_id text NOT NULL,correlation_id text NOT NULL,version integer NOT NULL CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(release,capability));
CREATE TABLE operations.release_rollout_events(id text PRIMARY KEY,rollout_id text NOT NULL REFERENCES operations.release_rollouts(id) ON DELETE RESTRICT,release text NOT NULL,capability text NOT NULL,from_phase text NOT NULL,to_phase text NOT NULL,cohort text NOT NULL,evidence jsonb NOT NULL,reason text NOT NULL,actor_id text NOT NULL,correlation_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX release_rollout_events_lookup_idx ON operations.release_rollout_events(release,capability,created_at DESC);
CREATE TRIGGER release_rollout_events_no_mutation BEFORE UPDATE OR DELETE ON operations.release_rollout_events FOR EACH ROW EXECUTE FUNCTION operations.reject_elevated_action_mutation();
DO $p$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='oneshowseo_app')THEN GRANT SELECT,INSERT,UPDATE ON operations.release_rollouts TO oneshowseo_app;GRANT SELECT,INSERT ON operations.release_rollout_events TO oneshowseo_app;REVOKE DELETE ON operations.release_rollouts,operations.release_rollout_events FROM oneshowseo_app;REVOKE UPDATE ON operations.release_rollout_events FROM oneshowseo_app;END IF;END $p$;
